package com.ias.stock;
import com.ias.trust.Problem;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;
import static com.ias.stock.StockExecutions.*;
import static com.ias.stock.StockFinanceGeneration.*;

class StockFinanceGenerationTest {
 StockExecutionsTest f;Binding binding;StockFinanceGeneration barrier;
 AtomicReference<List<UUID>> scoped=new AtomicReference<>(List.of()),pending=new AtomicReference<>(List.of());
 @BeforeEach void setup()throws Exception{f=new StockExecutionsTest();f.setup();binding=binding(1,"a".repeat(64));barrier=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"IN_PROGRESS","b".repeat(64),scoped.get(),pending.get()));}
 Binding binding(long generation,String digest){return new Binding(1,2,UUID.fromString(f.approval.ticketId()),UUID.fromString(f.approval.roundId()),UUID.randomUUID(),0,UUID.randomUUID(),UUID.randomUUID(),digest,UUID.randomUUID(),generation);}
 void delivered(UUID op)throws Exception{try(var c=f.db.getConnection()){update(c,"INSERT INTO stock_execution_delivery VALUES(1,?,?,CURRENT_TIMESTAMP)",op.toString(),"c".repeat(64));}}
 @Test void absentProtocolCreatesNoFenceAndNoGenerationRow()throws Exception{assertEquals("FINANCE_SOURCE_PROTOCOL_NOT_CONFIGURED",assertThrows(Problem.class,()->new StockFinanceGeneration(f.db).freeze(binding)).code);assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_generation"));}
 @Test void emptyOwnerStillPersistsFenceSnapshotAuditAndImmutableAck()throws Exception{var first=barrier.freeze(binding);assertEquals("OWNER_FENCED",first.state());assertFalse(first.globalFreezeAck());assertEquals("stock",first.receipt().owner());assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_fence"));assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_ack"));assertEquals(2,f.number("SELECT COUNT(*) FROM stock_finance_barrier_audit"));assertEquals(first,barrier.freeze(binding));assertEquals(1,f.number("SELECT generation FROM stock_finance_generation"));}
 @Test void fenceFirstPreventsDelayedNewQuantityMutationButNotHistoricalPureReads()throws Exception{barrier.freeze(binding);assertEquals("STOCK_FINANCE_GENERATION_FENCED",assertThrows(Problem.class,()->f.exec(Action.RESERVE,0,Map.of())).code);assertEquals(0,f.held());assertEquals(1,f.number("SELECT COUNT(*) FROM stock_execution_operation WHERE result_json LIKE '%REJECTED:STOCK_FINANCE_GENERATION_FENCED%'"));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_execution_fact"));}
 @Test void executionFirstRemainsRealAndHistoricalReplayDoesNotExecuteAgain()throws Exception{var command=f.cmd(Action.RESERVE,0,Map.of());var receipt=f.ledger.execute(f.actor,command);delivered(command.operationId());scoped.set(List.of(command.operationId()));var frozen=barrier.freeze(binding);assertEquals("OWNER_FENCED",frozen.state());assertTrue(frozen.receipt().localSnapshot().stream().anyMatch(x->"OPERATION".equals(x.get("type"))));assertEquals(receipt,f.ledger.execute(f.actor,command));assertEquals(2,f.held());assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_execution_fact"));assertEquals(0,f.number("SELECT generation FROM stock_finance_execution_fact"));}
 @Test void unknownLocalAckNeverProducesOwnerAckThenSameFreezeRecovers()throws Exception{var result=f.exec(Action.RESERVE,0,Map.of());scoped.set(List.of(result.operationId()));var waiting=barrier.freeze(binding);assertEquals("WAITING_OWNER_OPERATIONS",waiting.state());assertNull(waiting.receipt());assertTrue(waiting.unresolved().stream().anyMatch(s->s.startsWith("LOCAL_ACK_UNKNOWN:")));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_ack"));delivered(result.operationId());var ack=barrier.freeze(binding);assertEquals("OWNER_FENCED",ack.state());assertEquals(1,f.number("SELECT generation FROM stock_finance_generation"));}
 @Test void remoteInFlightAndMissingLocalReceiptCannotBeAcknowledged()throws Exception{UUID op=UUID.randomUUID();scoped.set(List.of(op));pending.set(List.of(op));var outcome=barrier.freeze(binding);assertEquals("WAITING_OWNER_OPERATIONS",outcome.state());assertTrue(outcome.unresolved().contains("W_IN_FLIGHT:"+op));assertTrue(outcome.unresolved().contains("LOCAL_RESULT_MISSING:"+op));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_ack"));}
 @Test void returnedCleanupCanProceedAfterFenceWithoutAllowingNewUse()throws Exception{var reserve=f.exec(Action.RESERVE,0,Map.of());delivered(reserve.operationId());var issue=f.exec(Action.ISSUE,1,Map.of());delivered(issue.operationId());scoped.set(List.of(reserve.operationId(),issue.operationId()));assertEquals("OWNER_FENCED",barrier.freeze(binding).state());assertEquals(409,assertThrows(Problem.class,()->f.exec(Action.USE,2,Map.of(101L,1L))).status);var returned=f.exec(Action.RETURN,2,Map.of(101L,2L));assertEquals("RETURNED",returned.state());assertEquals(10,f.hand());assertEquals(1,f.number("SELECT generation FROM stock_finance_execution_fact WHERE phase='RETURN'"));}
 @Test void ownerAckAuditFailureRollsBackEntireFenceAndOriginalFreezeRecovers()throws Exception{f.sql("ALTER TABLE stock_finance_barrier_audit ADD CONSTRAINT qa_ack_fail CHECK(phase<>'OWNER_ACKED')");assertThrows(Exception.class,()->barrier.freeze(binding));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_fence"));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_ack"));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_generation"));f.sql("ALTER TABLE stock_finance_barrier_audit DROP CONSTRAINT qa_ack_fail");assertEquals("OWNER_FENCED",barrier.freeze(binding).state());}
 @Test void sixConcurrentOriginalFreezeRequestsHaveOneAckAndTwoAuditFacts()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var futures=new ArrayList<Future<Outcome>>();for(int i=0;i<6;i++)futures.add(pool.submit(()->{gate.await();return barrier.freeze(binding);}));gate.countDown();var first=futures.getFirst().get();for(var task:futures)assertEquals(first,task.get());}assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_ack"));assertEquals(2,f.number("SELECT COUNT(*) FROM stock_finance_barrier_audit"));}
 @Test void sameFreezeChangedCommandOrTicketProofIs409AndGenerationCannotSkip()throws Exception{assertEquals(409,assertThrows(Problem.class,()->barrier.freeze(binding(2,"a".repeat(64)))).status);barrier.freeze(binding);var changed=new Binding(binding.tenantId(),binding.companyId(),binding.ticketId(),binding.roundId(),binding.groupId(),binding.expectedGroupVersion(),binding.quoteId(),binding.sourceOperationId(),"d".repeat(64),binding.freezeId(),binding.generation());assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(Problem.class,()->barrier.freeze(changed)).code);var changedParent=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"IN_PROGRESS","e".repeat(64),List.of(),List.of()));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(Problem.class,()->changedParent.freeze(binding)).code);}
 @Test void sourceAbortOrMismatchedTenantBindingCannotFenceOtherOwner()throws Exception{var aborted=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"ABORTED","b".repeat(64),List.of(),List.of()));assertEquals("FINANCE_SOURCE_ABORTED",assertThrows(Problem.class,()->aborted.freeze(binding)).code);var other=new Binding(2,2,binding.ticketId(),binding.roundId(),binding.groupId(),0,binding.quoteId(),binding.sourceOperationId(),binding.commandDigest(),binding.freezeId(),1);var wrong=new StockFinanceGeneration(f.db,b->new VerifiedFence(other,"IN_PROGRESS","b".repeat(64),List.of(),List.of()));assertEquals(503,assertThrows(Problem.class,()->wrong.freeze(binding)).status);assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_fence"));}
 @Test void issuingTransactionGenerationFactFailureRollsBackQuantitiesAndOriginalOperation()throws Exception{f.sql("ALTER TABLE stock_finance_execution_fact ADD CONSTRAINT qa_generation_fact CHECK(phase<>'RESERVE')");var command=f.cmd(Action.RESERVE,0,Map.of());assertThrows(Exception.class,()->f.ledger.execute(f.actor,command));assertEquals(0,f.held());assertEquals(0,f.number("SELECT COUNT(*) FROM stock_execution_operation"));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_execution_fact"));f.sql("ALTER TABLE stock_finance_execution_fact DROP CONSTRAINT qa_generation_fact");f.ledger.execute(f.actor,command);assertEquals(2,f.held());assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_execution_fact"));}
 @Test void unknownCommitDoesNotRollbackResetCloseOrReuseQuarantinedConnection()throws Exception{
  var real=f.db.getConnection();var connection=org.mockito.Mockito.mock(java.sql.Connection.class,org.mockito.AdditionalAnswers.delegatesTo(real));
  org.mockito.Mockito.doThrow(new java.sql.SQLException("uncertain commit")).when(connection).commit();org.mockito.Mockito.doThrow(new java.sql.SQLException("abort failed")).when(connection).abort(org.mockito.ArgumentMatchers.any());
  var ds=org.mockito.Mockito.mock(javax.sql.DataSource.class);org.mockito.Mockito.when(ds.getConnection()).thenReturn(connection);var isolated=new StockFinanceGeneration(ds,b->new VerifiedFence(b,"IN_PROGRESS","b".repeat(64),List.of(),List.of()));
  assertThrows(java.sql.SQLException.class,()->isolated.freeze(binding));org.mockito.Mockito.verify(connection,org.mockito.Mockito.never()).rollback();org.mockito.Mockito.verify(connection,org.mockito.Mockito.never()).close();org.mockito.Mockito.verify(connection,org.mockito.Mockito.never()).setAutoCommit(true);
  assertThrows(java.sql.SQLException.class,()->isolated.freeze(binding));org.mockito.Mockito.verify(ds,org.mockito.Mockito.times(1)).getConnection();real.rollback();real.close();
 }
 @Test void failedRollbackAbortsWithoutReturningOrResettingConnection()throws Exception{
  f.sql("ALTER TABLE stock_finance_barrier_audit ADD CONSTRAINT qa_abort_failure CHECK(phase<>'OWNER_ACKED')");var real=f.db.getConnection();var connection=org.mockito.Mockito.mock(java.sql.Connection.class,org.mockito.AdditionalAnswers.delegatesTo(real));org.mockito.Mockito.doThrow(new java.sql.SQLException("rollback failed")).when(connection).rollback();org.mockito.Mockito.doNothing().when(connection).abort(org.mockito.ArgumentMatchers.any());
  var ds=org.mockito.Mockito.mock(javax.sql.DataSource.class);org.mockito.Mockito.when(ds.getConnection()).thenReturn(connection);var isolated=new StockFinanceGeneration(ds,b->new VerifiedFence(b,"IN_PROGRESS","b".repeat(64),List.of(),List.of()));
  assertThrows(java.sql.SQLException.class,()->isolated.freeze(binding));org.mockito.Mockito.verify(connection).abort(org.mockito.ArgumentMatchers.any());org.mockito.Mockito.verify(connection,org.mockito.Mockito.never()).close();org.mockito.Mockito.verify(connection,org.mockito.Mockito.never()).setAutoCommit(true);real.rollback();real.close();assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_fence"));
 }
 @Test void committedReleaseRequiresAckAndKeepsImmutableTerminalHistory()throws Exception{
  barrier.freeze(binding);var terminal=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"COMMITTED","b".repeat(64),List.of(),List.of(),"c".repeat(64)));var first=terminal.release(binding);assertEquals("OWNER_RELEASED",first.get("state"));assertEquals(first,terminal.release(binding));assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_terminal"));assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_terminal_audit"));try(var c=f.db.getConnection()){assertFalse(StockFinanceGeneration.lock(c,1,binding.ticketId().toString()).fenced());}assertEquals(1,f.number("SELECT generation FROM stock_finance_generation"));
 }
 @Test void abortBeforePreparationPersistsNoExecutionTombstoneNotFakeAck()throws Exception{
  var terminal=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"ABORTED","b".repeat(64),List.of(),List.of()));var result=terminal.release(binding);assertNull(result.get("resultDigest"));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_fence"));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_ack"));assertEquals(1,f.number("SELECT generation FROM stock_finance_generation"));assertThrows(Problem.class,()->barrier.freeze(binding));
 }
 @Test void terminalAuditFailureRetainsActiveFenceThenSameBindingRecovers()throws Exception{
  barrier.freeze(binding);f.sql("ALTER TABLE stock_finance_terminal_audit ADD CONSTRAINT qa_terminal_fail CHECK(source_state<>'ABORTED')");var terminal=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"ABORTED","b".repeat(64),List.of(),List.of()));assertThrows(Exception.class,()->terminal.release(binding));assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_terminal"));assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_generation WHERE active_freeze_id IS NOT NULL"));f.sql("ALTER TABLE stock_finance_terminal_audit DROP CONSTRAINT qa_terminal_fail");assertEquals("OWNER_RELEASED",terminal.release(binding).get("state"));
 }
 @Test void missingProofAndUncommittedStateCannotRelease()throws Exception{
  barrier.freeze(binding);assertEquals(503,assertThrows(Problem.class,()->barrier.release(binding)).status);var unavailable=new StockFinanceGeneration(f.db,b->{throw new Problem(404,"NOT_OBSERVED");});assertEquals(404,assertThrows(Problem.class,()->unavailable.release(binding)).status);assertEquals(0,f.number("SELECT COUNT(*) FROM stock_finance_terminal"));assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_generation WHERE active_freeze_id IS NOT NULL"));
 }
 @Test void oldTerminalCannotClearNewGenerationOrChangeResult()throws Exception{
  var aborted=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"ABORTED","b".repeat(64),List.of(),List.of()));var old=aborted.release(binding);var next=binding(2,"e".repeat(64));barrier.freeze(next);assertEquals(old,aborted.release(binding));assertEquals(2,f.number("SELECT generation FROM stock_finance_generation"));assertEquals(1,f.number("SELECT COUNT(*) FROM stock_finance_generation WHERE active_freeze_id IS NOT NULL"));var changed=new StockFinanceGeneration(f.db,b->new VerifiedFence(b,"COMMITTED","b".repeat(64),List.of(),List.of(),"c".repeat(64)));assertThrows(Problem.class,()->changed.release(binding));
 }
}
